import { Controller } from "@hotwired/stimulus"

// Option rows on the question form: "Add option" appends a row with the next
// number, the ✕ button removes a row. Rows are renumbered so labels always
// read "Option 1", "Option 2"... and "Option 1 is correct"... in order.
// The server reads rows in document order, so param indexes only need to be unique.
export default class extends Controller {
  static targets = [ "list", "row", "template" ]
  static values = { nextIndex: Number }

  add(event) {
    event.preventDefault()
    const html = this.templateTarget.innerHTML
      .replaceAll("NEW_INDEX", this.nextIndexValue++)
      .replaceAll("NEW_NUMBER", this.rowTargets.length + 1)
    this.listTarget.insertAdjacentHTML("beforeend", html)
    this.renumber()
    this.rowTargets.at(-1).querySelector("[data-role=title]").focus()
  }

  remove(event) {
    event.preventDefault()
    const row = event.target.closest("[data-option-rows-target=row]")
    const next = row.nextElementSibling || row.previousElementSibling
    row.remove()
    this.renumber()
    next?.querySelector("[data-role=title]")?.focus()
  }

  renumber() {
    this.rowTargets.forEach((row, index) => {
      const number = index + 1
      row.querySelector("[data-role=title-label]").textContent = `Option ${number}`
      row.querySelector("[data-role=title]").placeholder = `Option ${number}`
      row.querySelector("[data-role=correct-label]").textContent = `Option ${number} is `
    })
  }
}
